// Les questions du jeu « Explorateur du temps » (environ 200).
// Chaque partie en tire 20 au hasard (dans un thème ou dans tous), et mélange l'ordre des réponses.
// Format : Q(thème, question, [BONNE RÉPONSE, autre, autre…], explication, où chercher ?)
// → la bonne réponse est TOUJOURS écrite en premier ici ; le jeu la mélange à l'affichage.
// Toutes les réponses se trouvent sur le site (frises, fiches, arbre du vivant, Tout voir).

export const THEMES = {
  univers: { nom: 'Univers et Terre', ou: { texte: 'Étages Univers et Terre', lien: '#univers' } },
  vie: { nom: 'La vie et les animaux', ou: { texte: 'Étage Vie (frise, périodes et arbre du vivant)', lien: '#/vie' } },
  humains: { nom: 'Les humains', ou: { texte: 'Étage Humains', lien: '#/humains' } },
  histoire: { nom: 'L’Histoire du monde', ou: { texte: 'Page Histoire (choisir les lieux)', lien: '#/histoire' } },
  france: { nom: 'L’histoire de France', ou: { texte: 'Page Histoire, lieu « France »', lien: '#/histoire' } },
  aujourdhui: { nom: 'Aujourd’hui', ou: { texte: 'Étage Aujourd’hui', lien: '#/aujourdhui' } },
};

let n = 0;
const Q = (theme, q, choix, explication, ou) => ({ id: `q${++n}`, theme, q, choix, explication, ou: ou || THEMES[theme].ou });
